const territories={
  prompts:{number:'01 / A BIBLIOTECA DAS IDEIAS',name:'A Biblioteca das Ideias.',lead:'O lugar onde perguntas vagas se transformam em conversas produtivas com a inteligência artificial.',promise:'Não é uma coleção de frases mágicas. É um espaço para aprender a pensar, perguntar, revisar e decidir com mais clareza.',location:'ALA NORTE · LINGUAGEM E INVESTIGAÇÃO',question:'Uma boa resposta começa antes do prompt.',thesis:'Quando o problema não está claro, uma instrução sofisticada só produz uma resposta sofisticadamente errada. Aqui a proposta é partir do contexto, formular hipóteses e pedir à IA entregas verificáveis.',principles:[['Contexto','O que a ferramenta precisa conhecer para não inventar o cenário?'],['Critério','Como saber se a resposta serve para uma decisão real?'],['Revisão','Quais conclusões dependem de confirmação humana?']],sectionTitle:'Três portas para começar.',sectionLead:'Cada experiência resolve uma situação concreta. Entre por aquilo que está travando seu trabalho hoje.',features:[['Diagnosticar um processo','Investigue etapas, filas, retrabalho e possíveis causas antes de pensar em automação.','material.html?id=diagnostico-processos&from=Prompts'],['Comparar decisões','Estruture alternativas, riscos, critérios e experimentos reversíveis.','material.html?id=decisao-negocio&from=Prompts'],['Transformar reunião em ação','Organize decisões, responsáveis, pendências e próximos passos sem inventar fatos.','material.html?id=ata-plano&from=Prompts']],practiceTitle:'Pergunte menos à máquina. Investigue mais o problema.',practiceText:'Comece com uma situação real, descreva o objetivo e só depois escolha a ferramenta. O trabalho importante está nas perguntas que você faz ao longo do caminho.',practiceAction:'Mapeie um gargalo da sua operação.',practiceDetail:'Uma entrevista guiada em cinco fases, com separação entre fatos, hipóteses e dados faltantes.',primary:'material.html?id=diagnostico-processos&from=Prompts',related:'gestao',relatedTitle:'A Mesa dos Projetos',relatedText:'Leve o diagnóstico para a execução ↗'},
  skills:{number:'02 / O OBSERVATÓRIO DOS MÉTODOS',name:'O Observatório dos Métodos.',lead:'Conhecimento que deixa de depender da memória e passa a existir como processo repetível.',promise:'Aqui um método tem início, etapas, critérios de qualidade e limites. A consistência importa mais que a aparência de automação.',location:'COPA ALTA · SISTEMAS E ROTINAS',question:'O que você sabe fazer que precisa ser reproduzível?',thesis:'Uma skill bem construída não é simplesmente um prompt mais longo: ela carrega regras de decisão, materiais de referência e uma forma de verificar se a tarefa foi bem executada.',principles:[['Método','Qual sequência torna o resultado menos dependente do improviso?'],['Limites','Quando a rotina deve pedir ajuda ou interromper a execução?'],['Qualidade','Como conferir a entrega antes de confiar nela?']],sectionTitle:'Métodos que merecem ser observados.',sectionLead:'Estude processos, adapte ao seu contexto e preserve o julgamento humano.',features:[['Método MAPEAR','Investigar a dor, auditar o processo, provar a causa e redesenhar antes de automatizar.','material.html?id=mapear&from=Skills'],['Motivações de compra','Examinar desejos, fricções e hipóteses de posicionamento sem confundir suposição com evidência.','material.html?id=motivacoes-compra&from=Skills'],['Da ideia ao MVP','Organizar validação, escopo mínimo e decisões de avanço para um novo produto.','material.html?id=novos-produtos&from=Skills']],practiceTitle:'Transforme conhecimento em procedimento.',practiceText:'Escolha uma atividade que você repete. Documente o gatilho, os dados de entrada, os passos, os critérios de saída e os pontos que exigem aprovação.',practiceAction:'Conheça o Método MAPEAR.',practiceDetail:'Um caminho estruturado para investigar causas antes de propor soluções.',primary:'material.html?id=mapear&from=Skills',related:'ia',relatedTitle:'A Forja da Inteligência',relatedText:'Descubra onde transformar método em sistema ↗'},
  codigos:{number:'03 / O ARQUIVO DOS CÓDIGOS',name:'O Arquivo dos Códigos.',lead:'Uma oficina aberta para compreender o que existe dentro das ferramentas de inteligência artificial.',promise:'O código é uma fonte para estudar e experimentar; repositórios externos não são produtos criados por Rafael nem soluções prontas para uso empresarial.',location:'RAÍZES PROFUNDAS · CONSTRUÇÃO DIGITAL',question:'O que acontece por trás da interface?',thesis:'Para construir algo sólido, vale conhecer bibliotecas, documentação, permissões e limites. Este ambiente liga conceitos a exemplos técnicos e mantém a origem de cada projeto visível.',principles:[['Arquitetura','Que componentes conversam entre si?'],['Segurança','Quais ferramentas e dados o software pode acessar?'],['Origem','Quem mantém o projeto e sob qual documentação?']],sectionTitle:'Abra o código, entenda as escolhas.',sectionLead:'Três caminhos técnicos para quem quer sair da superfície.',features:[['Agentes e ferramentas','Um guia em português sobre agentes, execução, delegação e SDK oficial da OpenAI.','agentes-ia.html'],['Servidores MCP','Referências para conectar aplicações a ferramentas de forma controlada.','material.html?id=mcp-servidores&from=Reposit%C3%B3rios'],['Claude Code','Uma visão sobre o trabalho de programação com agentes e seu repositório.','material.html?id=claude-code&from=Reposit%C3%B3rios']],practiceTitle:'Entenda primeiro. Execute depois.',practiceText:'Revise requisitos, licença, versões e permissões. Teste com dados fictícios e acompanhe custos e falhas antes de integrar um sistema real.',practiceAction:'Como funcionam agentes de IA?',practiceDetail:'Da ideia de um agente até a documentação, um exemplo de código e o download do repositório.',primary:'agentes-ia.html',related:'ia',relatedTitle:'A Forja da Inteligência',relatedText:'Transforme possibilidades técnicas em casos de uso ↗'},
  gestao:{number:'04 / A MESA DOS PROJETOS',name:'A Mesa dos Projetos.',lead:'O lugar das decisões que precisam virar entregas, responsáveis, indicadores e resultados.',promise:'Experiência prática de gestão e controle aplicada à execução: menos improviso, mais visibilidade sobre escopo, custos e riscos.',location:'TERRAÇO CENTRAL · PROJETOS E EXECUÇÃO',question:'Um projeto está avançando ou apenas consumindo esforço?',thesis:'Projetos complexos ensinam que o movimento não é o mesmo que progresso. Na mesa, cada iniciativa precisa ter um problema claro, patrocinador, entregas, limites e mecanismos de acompanhamento.',principles:[['Escopo','O que está dentro — e fora — do combinado?'],['Controle','Quais sinais revelam atrasos e desvios a tempo de agir?'],['Responsabilidade','Quem decide, executa, aprova e responde pelo resultado?']],sectionTitle:'A anatomia de uma boa execução.',sectionLead:'Da primeira conversa ao aprendizado depois da entrega.',features:[['Antes de começar','Um checklist sobre objetivo, escopo, papéis, riscos e critérios de sucesso.','material.html?id=projetos-checklist&from=Gest%C3%A3o'],['Controle e indicadores','Entenda por que métricas precisam de linha de base, fonte e frequência.','material.html?id=metricas-ia&from=IA%20aplicada'],['Minha experiência','Projetos de infraestrutura e sistemas metroferroviários que moldaram minha visão de gestão.','historia.html#sobre']],practiceTitle:'Faça sua próxima reunião de projeto render.',practiceText:'Saia com decisões registradas, responsáveis definidos, pendências evidentes e um momento combinado para revisar desvios. Controle nasce da visibilidade.',practiceAction:'Confira o checklist de início.',practiceDetail:'Uma lista simples para alinhar objetivos, entregas, riscos e quem aprova mudanças.',primary:'material.html?id=projetos-checklist&from=Gest%C3%A3o',related:'estrategia',relatedTitle:'O Conselho das Decisões',relatedText:'Escolha o que merece começar primeiro ↗'},
  ia:{number:'05 / A FORJA DA INTELIGÊNCIA',name:'A Forja da Inteligência.',lead:'Onde tecnologia encontra operação: um espaço para transformar hipóteses em pequenos experimentos reais.',promise:'IA não é o ponto de partida. Primeiro identifique a tarefa, os riscos e a medida de sucesso; só então escolha o tipo de solução.',location:'OFICINA LESTE · PROTÓTIPOS E SISTEMAS',question:'Qual trabalho vale a pena entregar à IA?',thesis:'Nem tudo precisa de um agente autônomo. Às vezes uma automação tradicional ou uma melhoria simples no processo resolve melhor. Aqui o foco é distinguir essas alternativas e testar com responsabilidade.',principles:[['Oportunidade','Há frequência, volume e uma dor mensurável?'],['Supervisão','Onde entram as decisões humanas e os limites de acesso?'],['Piloto','Que experimento pequeno prova valor sem criar dependência?']],sectionTitle:'Da possibilidade à aplicação.',sectionLead:'Explore critérios, arquitetura e medição de resultados.',features:[['Encontrar oportunidades','Identifique tarefas candidatas e avalie riscos de automatização.','material.html?id=agentes-oportunidade&from=IA%20aplicada'],['Medir resultados','Construa indicadores antes de comparar o antes e o depois.','material.html?id=metricas-ia&from=IA%20aplicada'],['Entender agentes','Descubra o que um agente faz, quando usar ferramentas e o que exige revisão humana.','agentes-ia.html']],practiceTitle:'Prove valor antes de escalar.',practiceText:'Defina um caso de uso, faça um teste limitado com entradas autorizadas, registre erros e compare custo, qualidade e tempo com o processo atual.',practiceAction:'Avalie sua primeira oportunidade.',practiceDetail:'Um roteiro para decidir se a tarefa precisa de IA, automação simples ou apenas processo melhor.',primary:'material.html?id=agentes-oportunidade&from=IA%20aplicada',related:'codigos',relatedTitle:'O Arquivo dos Códigos',relatedText:'Conheça as ferramentas por trás da solução ↗'},
  estrategia:{number:'06 / O CONSELHO DAS DECISÕES',name:'O Conselho das Decisões.',lead:'Uma sala para olhar alternativas, assumir incertezas e escolher caminhos que você consiga sustentar.',promise:'Estratégia não é uma lista de ideias inspiradoras. É decidir prioridades, explicitar renúncias e estabelecer quando mudar de direção.',location:'VARANDA ALTA · VISÃO E ESCOLHAS',question:'Se tudo é prioridade, o que realmente importa?',thesis:'Uma boa decisão conecta objetivo, evidências, riscos, recursos e tempo. O papel deste ambiente é ajudar a pensar antes de comprometer dinheiro, pessoas e reputação.',principles:[['Opções','Quais alternativas reais estão sobre a mesa?'],['Trade-offs','O que você abre mão ao escolher cada caminho?'],['Sinais','Que evidência faria você continuar, ajustar ou parar?']],sectionTitle:'Decisões são construídas.',sectionLead:'Comece pelo que está indefinido, não pela resposta mais confortável.',features:[['Priorizar sem achismo','Compare impacto, urgência, esforço e riscos com critérios explícitos.','material.html?id=priorizacao&from=Estrat%C3%A9gia'],['Decisões difíceis','Estruture cenários, hipóteses e um primeiro teste reversível.','material.html?id=decisao-negocio&from=Prompts'],['Desenhar um novo produto','Descubra o problema antes de investir no produto.','material.html?id=novos-produtos&from=Skills']],practiceTitle:'Uma escolha fica melhor quando pode ser revisada.',practiceText:'Registre a hipótese, a evidência disponível, o custo de oportunidade e um gatilho claro para reavaliar. Assim você não transforma convicção em teimosia.',practiceAction:'Escolha a próxima prioridade.',practiceDetail:'Um modelo para comparar iniciativas com transparência e responsabilidade.',primary:'material.html?id=priorizacao&from=Estrat%C3%A9gia',related:'gestao',relatedTitle:'A Mesa dos Projetos',relatedText:'Tire a escolha do papel e execute ↗'}
};
const key=new URLSearchParams(location.search).get('lugar')||'gestao';const item=territories[key];if(!item){location.replace('index.html')}else{
  const set=(id,value)=>document.getElementById(id).textContent=value;
  ['number','name','lead','promise','location','question','thesis','sectionTitle','sectionLead','practiceTitle','practiceText','practiceAction','practiceDetail','relatedTitle','relatedText'].forEach(id=>set(id,item[id]));
  document.title=item.name+' — Rafael Rein';document.getElementById('primaryLink').href=item.primary;document.getElementById('related').href='territorio.html?lugar='+item.related;
  const make=(parent,values,css)=>{for(const row of values){const el=document.createElement(css==='principle'?'article':'a');el.className=css;if(css==='feature-card'){el.href=row[2];el.innerHTML='<span>EXPLORE ESTE TEMA ↗</span><h3></h3><p></p>';el.querySelector('h3').textContent=row[0];el.querySelector('p').textContent=row[1]}else{const h=document.createElement('h3');h.textContent=row[0];const p=document.createElement('p');p.textContent=row[1];el.append(h,p)}parent.append(el)}};
  make(document.getElementById('principles'),item.principles,'principle');make(document.getElementById('features'),item.features,'feature-card');
}
